insert into public.products (slug, name, name_fr, description, description_fr, kind, status)
values
  ('acid-oversized-tshirt', 'تي شيرت أوفرسايز أسيد', 'T-shirt Oversize Acid', 'تي شيرت أوفرسايز بقصة واسعة وقطن ثقيل، بلمسة أسيد مميزة. مريح للاستعمال اليومي ومحافظ على شكله بعد الغسل.', 'T-shirt oversize en coton lourd, finition acidulée. Confortable au quotidien.', 'single', 'published'),
  ('polo-demi-manches', 'قميص بولو نص كم', 'Polo demi-manches', 'قميص بولو نص كم بقماش بيّكيه مريح، بياقة كلاسيكية وأزرار. متوفر بعشرات الألوان لتختار ما يناسبك.', 'Polo demi-manches en piqué, col classique. Disponible en de nombreuses couleurs.', 'single', 'published'),
  ('sacoche-bandouliere', 'حقيبة كتف', 'Sacoche bandoulière', 'حقيبة كتف صغيرة بحزام قابل للتعديل وجيوب منظمة. خفيفة وعملية، تناسب الهاتف والمحفظة والمفاتيح.', 'Sacoche bandoulière réglable, légère et pratique.', 'single', 'published'),
  ('short-classique', 'شورت', 'Short', 'شورت بقصة مريحة وخامة خفيفة، مناسب للصيف والرياضة. خصر مطاطي بخطوط قابلة للشد.', 'Short coupe confortable, tissu léger, taille élastique.', 'single', 'published'),
  ('tshirt-oversize-premium', 'تي شيرت أوفرسايز بريميوم', 'T-shirt Oversize Premium', 'تي شيرت أوفرسايز بريميوم بقطن سميك وملمس ناعم. قصة عريضة عند الكتفين وطول مناسب.', 'T-shirt oversize premium, coton épais et toucher doux.', 'single', 'published'),
  ('tshirt-oversize-basic', 'تي شيرت أوفرسايز بيسيك', 'T-shirt Oversize Basic', 'تي شيرت أوفرسايز أساسي، اختيار يومي بجودة ثابتة وسعر مناسب. متوفر بأربعة ألوان.', 'T-shirt oversize basic, qualité constante et bon prix.', 'single', 'published'),
  ('tshirt-regular', 'تي شيرت عادي', 'T-shirt Regular', 'تي شيرت بقصة عادية كلاسيكية، يناسب كل الإطلالات. أكثر من عشرين لوناً للاختيار.', 'T-shirt coupe regular, plus de vingt coloris.', 'single', 'published'),
  ('tshirt-260gsm-oversized', 'تي شيرت أوفرسايز 260 غرام', 'T-shirt Oversize 260 GSM', 'تي شيرت بقطن 260 غرام، سميك وثقيل ويحافظ على قوامه. القطعة التي تدوم بعد عشرات الغسلات.', 'T-shirt 260 GSM, coton épais qui garde sa forme.', 'single', 'published'),
  ('tshirt-oversized-plus', 'تي شيرت أوفرسايز بليس', 'T-shirt Oversize Plus', 'تي شيرت أوفرسايز بمقاسات واسعة أكثر، مخصص لمن يفضّل قصة فضفاضة. سبعة ألوان.', 'T-shirt oversize aux coupes plus larges, sept coloris.', 'single', 'published'),
  ('wide-short', 'شورت واسع', 'Wide Short', 'شورت واسع بقصة عريضة وطول فوق الركبة. مريح جداً في الحرارة، مع خصر مطاطي.', 'Short large, coupe ample, confortable par forte chaleur.', 'single', 'published')
