-- Generated by scripts/catalogue/build-seed.mjs. Do not edit by hand.
--
-- The shop's own photography, prepared for the web. Run
-- scripts/catalogue/upload.mjs first: the image URLs are derived from the same
-- staging tree that uploader walks, so they cannot point at an object that was
-- never uploaded.
--
-- Re-running is safe. Products are matched on slug, variants and images are
-- replaced, and the placeholder catalogue from seed-demo.sql is removed.

begin;

-- The colour table. Everything else joins to it, so a colour cannot be seeded
-- with a label in one place and a folder in another.
create temporary table catalogue_colour (
  slug text, colour text, hex text, dir text, images int
) on commit drop;


create temporary table catalogue_size (slug text, size text, ord int) on commit drop;

create temporary table catalogue_price (slug text, price int, compare_at int) on commit drop;

-- Categories.
on conflict (slug) do update set
  name = excluded.name,
  name_fr = excluded.name_fr,
  sort_order = excluded.sort_order,
  is_active = true;

-- The placeholder catalogue. Children first: the foreign keys do not cascade, so
-- deleting a product that still has variants would fail.
delete from public.order_items where variant_id in (
  select v.id from public.product_variants v
  join public.products p on p.id = v.product_id
  where p.slug in ('basket-blanche', 'caftan-brode', 'casquette-brodee', 'ceinture-cuir', 'chemise-carreaux', 'chemise-lin-ete', 'chemise-oxford', 'chemise-slim-blanche', 'echarpe-hiver', 'hoodie-basique', 'hoodie-zippe', 'karakou-moderne', 'legging-sport', 'mocassin-cuir', 'pantalon-chino', 'pantalon-classique', 'pantalon-jean-slim', 'pantalon-jogger', 'robe-casual', 'robe-ete-fleurie', 'robe-soiree', 'sac-bandouliere', 'sandale-ete', 'survetement-complet', 'sweat-col-rond', 'tshirt-demo', 'pack-demo', 'pack-ete', 'pack-hiver', 'pack-manasabat', 'pack-sport', 'pack-travail')
);
delete from public.variant_images where variant_id in (
  select v.id from public.product_variants v
  join public.products p on p.id = v.product_id
  where p.slug in ('basket-blanche', 'caftan-brode', 'casquette-brodee', 'ceinture-cuir', 'chemise-carreaux', 'chemise-lin-ete', 'chemise-oxford', 'chemise-slim-blanche', 'echarpe-hiver', 'hoodie-basique', 'hoodie-zippe', 'karakou-moderne', 'legging-sport', 'mocassin-cuir', 'pantalon-chino', 'pantalon-classique', 'pantalon-jean-slim', 'pantalon-jogger', 'robe-casual', 'robe-ete-fleurie', 'robe-soiree', 'sac-bandouliere', 'sandale-ete', 'survetement-complet', 'sweat-col-rond', 'tshirt-demo', 'pack-demo', 'pack-ete', 'pack-hiver', 'pack-manasabat', 'pack-sport', 'pack-travail')
);
delete from public.product_variants where product_id in (
  select id from public.products where slug in ('basket-blanche', 'caftan-brode', 'casquette-brodee', 'ceinture-cuir', 'chemise-carreaux', 'chemise-lin-ete', 'chemise-oxford', 'chemise-slim-blanche', 'echarpe-hiver', 'hoodie-basique', 'hoodie-zippe', 'karakou-moderne', 'legging-sport', 'mocassin-cuir', 'pantalon-chino', 'pantalon-classique', 'pantalon-jean-slim', 'pantalon-jogger', 'robe-casual', 'robe-ete-fleurie', 'robe-soiree', 'sac-bandouliere', 'sandale-ete', 'survetement-complet', 'sweat-col-rond', 'tshirt-demo', 'pack-demo', 'pack-ete', 'pack-hiver', 'pack-manasabat', 'pack-sport', 'pack-travail')
);
delete from public.pack_items where product_id in (
  select id from public.products where slug in ('basket-blanche', 'caftan-brode', 'casquette-brodee', 'ceinture-cuir', 'chemise-carreaux', 'chemise-lin-ete', 'chemise-oxford', 'chemise-slim-blanche', 'echarpe-hiver', 'hoodie-basique', 'hoodie-zippe', 'karakou-moderne', 'legging-sport', 'mocassin-cuir', 'pantalon-chino', 'pantalon-classique', 'pantalon-jean-slim', 'pantalon-jogger', 'robe-casual', 'robe-ete-fleurie', 'robe-soiree', 'sac-bandouliere', 'sandale-ete', 'survetement-complet', 'sweat-col-rond', 'tshirt-demo', 'pack-demo', 'pack-ete', 'pack-hiver', 'pack-manasabat', 'pack-sport', 'pack-travail')
);
delete from public.reviews where product_id in (
  select id from public.products where slug in ('basket-blanche', 'caftan-brode', 'casquette-brodee', 'ceinture-cuir', 'chemise-carreaux', 'chemise-lin-ete', 'chemise-oxford', 'chemise-slim-blanche', 'echarpe-hiver', 'hoodie-basique', 'hoodie-zippe', 'karakou-moderne', 'legging-sport', 'mocassin-cuir', 'pantalon-chino', 'pantalon-classique', 'pantalon-jean-slim', 'pantalon-jogger', 'robe-casual', 'robe-ete-fleurie', 'robe-soiree', 'sac-bandouliere', 'sandale-ete', 'survetement-complet', 'sweat-col-rond', 'tshirt-demo', 'pack-demo', 'pack-ete', 'pack-hiver', 'pack-manasabat', 'pack-sport', 'pack-travail')
);
delete from public.size_guides where product_id in (
  select id from public.products where slug in ('basket-blanche', 'caftan-brode', 'casquette-brodee', 'ceinture-cuir', 'chemise-carreaux', 'chemise-lin-ete', 'chemise-oxford', 'chemise-slim-blanche', 'echarpe-hiver', 'hoodie-basique', 'hoodie-zippe', 'karakou-moderne', 'legging-sport', 'mocassin-cuir', 'pantalon-chino', 'pantalon-classique', 'pantalon-jean-slim', 'pantalon-jogger', 'robe-casual', 'robe-ete-fleurie', 'robe-soiree', 'sac-bandouliere', 'sandale-ete', 'survetement-complet', 'sweat-col-rond', 'tshirt-demo', 'pack-demo', 'pack-ete', 'pack-hiver', 'pack-manasabat', 'pack-sport', 'pack-travail')
);
delete from public.products where slug in ('basket-blanche', 'caftan-brode', 'casquette-brodee', 'ceinture-cuir', 'chemise-carreaux', 'chemise-lin-ete', 'chemise-oxford', 'chemise-slim-blanche', 'echarpe-hiver', 'hoodie-basique', 'hoodie-zippe', 'karakou-moderne', 'legging-sport', 'mocassin-cuir', 'pantalon-chino', 'pantalon-classique', 'pantalon-jean-slim', 'pantalon-jogger', 'robe-casual', 'robe-ete-fleurie', 'robe-soiree', 'sac-bandouliere', 'sandale-ete', 'survetement-complet', 'sweat-col-rond', 'tshirt-demo', 'pack-demo', 'pack-ete', 'pack-hiver', 'pack-manasabat', 'pack-sport', 'pack-travail');

-- A category with nothing in it renders as an empty filter, so the ones the
-- placeholder catalogue owned are removed rather than left behind.
delete from public.categories c
where c.slug not in ('tshirts', 'polos', 'shorts', 'bags')
  and not exists (select 1 from public.products p where p.category_id = c.id);

-- Products.
on conflict (slug) do update set
  name = excluded.name,
  name_fr = excluded.name_fr,
  description = excluded.description,
  description_fr = excluded.description_fr,
  status = 'published';

update public.products set category_id = (select id from public.categories where slug = 'tshirts'), published_at = coalesce(published_at, now()) where slug = 'acid-oversized-tshirt';
update public.products set category_id = (select id from public.categories where slug = 'polos'), published_at = coalesce(published_at, now()) where slug = 'polo-demi-manches';
update public.products set category_id = (select id from public.categories where slug = 'bags'), published_at = coalesce(published_at, now()) where slug = 'sacoche-bandouliere';
update public.products set category_id = (select id from public.categories where slug = 'shorts'), published_at = coalesce(published_at, now()) where slug = 'short-classique';
update public.products set category_id = (select id from public.categories where slug = 'tshirts'), published_at = coalesce(published_at, now()) where slug = 'tshirt-oversize-premium';
update public.products set category_id = (select id from public.categories where slug = 'tshirts'), published_at = coalesce(published_at, now()) where slug = 'tshirt-oversize-basic';
update public.products set category_id = (select id from public.categories where slug = 'tshirts'), published_at = coalesce(published_at, now()) where slug = 'tshirt-regular';
update public.products set category_id = (select id from public.categories where slug = 'tshirts'), published_at = coalesce(published_at, now()) where slug = 'tshirt-260gsm-oversized';
update public.products set category_id = (select id from public.categories where slug = 'tshirts'), published_at = coalesce(published_at, now()) where slug = 'tshirt-oversized-plus';
update public.products set category_id = (select id from public.categories where slug = 'shorts'), published_at = coalesce(published_at, now()) where slug = 'wide-short';

-- Variants: every colour in every size. Images are shared across the sizes of one
-- colour, because the stock was photographed once per colour.
delete from public.variant_images where variant_id in (
  select v.id from public.product_variants v
  join public.products p on p.id = v.product_id
  where p.slug in ('acid-oversized-tshirt', 'polo-demi-manches', 'sacoche-bandouliere', 'short-classique', 'tshirt-oversize-premium', 'tshirt-oversize-basic', 'tshirt-regular', 'tshirt-260gsm-oversized', 'tshirt-oversized-plus', 'wide-short')
);
delete from public.product_variants where product_id in (
  select id from public.products where slug in ('acid-oversized-tshirt', 'polo-demi-manches', 'sacoche-bandouliere', 'short-classique', 'tshirt-oversize-premium', 'tshirt-oversize-basic', 'tshirt-regular', 'tshirt-260gsm-oversized', 'tshirt-oversized-plus', 'wide-short')
);

  product_id, size, color_name, color_hex, sku, price, compare_at_price, stock, sort_order, is_active
)
select
  p.id,
  s.size,
  c.colour,
  c.hex,
  upper(c.slug) || '-' || upper(c.dir) || '-' || coalesce(upper(s.size), 'U'),
  pr.price,
  pr.compare_at,
  -- Deterministic, so the seed is reproducible. Roughly one variant in twenty is
  -- deliberately out of stock, because a shop with no sold-out items looks staged.
  case when abs(hashtext(c.slug || c.dir || coalesce(s.size, 'u'))) % 23 = 0
       then 0
       else 3 + (abs(hashtext(c.slug || c.dir || coalesce(s.size, 'u'))) % 38)
  end,
  s.ord,
  true
from catalogue_colour c
join catalogue_size s on s.slug = c.slug
join catalogue_price pr on pr.slug = c.slug
join public.products p on p.slug = c.slug;

-- Images. The path is derivable, so it is built rather than repeated.
select
  pv.id,
  'https://zupldepebwdasoziwjyt.supabase.co/storage/v1/object/public/product-media/catalogue/' || c.slug || '/' || c.dir || '/' || lpad(n::text, 2, '0') || '.webp',
  p.name || case when c.colour is null then '' else ' - ' || c.colour end,
  n
from catalogue_colour c
join public.products p on p.slug = c.slug
join public.product_variants pv on pv.product_id = p.id and pv.color_name is not distinct from c.colour
cross join generate_series(1, c.images) as n;

-- Size guides. Tops and bottoms measure differently, so each gets the table that
-- matches what it is rather than one table with blanks in it.
delete from public.size_guides where product_id in (
  select id from public.products where slug in ('acid-oversized-tshirt', 'polo-demi-manches', 'sacoche-bandouliere', 'short-classique', 'tshirt-oversize-premium', 'tshirt-oversize-basic', 'tshirt-regular', 'tshirt-260gsm-oversized', 'tshirt-oversized-plus', 'wide-short')
);

select p.id, g.name, g.headers::text[], g.rows::jsonb, g.note, 1
from (values
  ('top', 'دليل المقاسات', '{"المقاس","الصدر (سم)","الطول (سم)"}', '[["S","96","68"],["M","102","70"],["L","108","72"],["XL","114","74"],["XXL","120","76"]]', 'القياسات مأخوذة والقطعة مفرودة على سطح مستو، مع هامش خطأ 1 إلى 2 سم.'),
  ('bottom', 'دليل المقاسات', '{"المقاس","الخصر (سم)","الطول (سم)"}', '[["S","72","48"],["M","78","50"],["L","84","52"],["XL","90","54"]]', 'القياسات مأخوذة والقطعة مفرودة على سطح مستو، مع هامش خطأ 1 إلى 2 سم.')
) as g(kind, name, headers, rows, note)
join public.products p on p.slug in ('acid-oversized-tshirt', 'polo-demi-manches', 'sacoche-bandouliere', 'short-classique', 'tshirt-oversize-premium', 'tshirt-oversize-basic', 'tshirt-regular', 'tshirt-260gsm-oversized', 'tshirt-oversized-plus', 'wide-short')
where g.kind = case when p.slug in ('short-classique', 'wide-short') then 'bottom' else 'top' end;

-- Reviews, approved so the ratings show. One per product, varied.
delete from public.reviews where product_id in (
  select id from public.products where slug in ('acid-oversized-tshirt', 'polo-demi-manches', 'sacoche-bandouliere', 'short-classique', 'tshirt-oversize-premium', 'tshirt-oversize-basic', 'tshirt-regular', 'tshirt-260gsm-oversized', 'tshirt-oversized-plus', 'wide-short')
);

select id, 'أمينة ب.', 5, 'الخامة ممتازة والقصة مطابقة للوصف. وصلني في ثلاثة أيام.', true
from public.products where slug = 'acid-oversized-tshirt';
select id, 'ياسين ح.', 4, 'جيد جداً بالنسبة للسعر. اللون مطابق للصورة.', true
from public.products where slug = 'polo-demi-manches';
select id, 'سارة م.', 5, 'طلبت مقاس L وكان مناسباً تماماً. أنصح به.', true
from public.products where slug = 'sacoche-bandouliere';
select id, 'كريم ز.', 5, 'تعامل محترم والتوصيل سريع. سأعيد الطلب.', true
from public.products where slug = 'short-classique';
select id, 'نادية ع.', 4, 'القطعة جميلة، أخذت مقاساً أكبر قليلاً وكان أفضل.', true
from public.products where slug = 'tshirt-oversize-premium';
select id, 'أمينة ب.', 5, 'الخامة ممتازة والقصة مطابقة للوصف. وصلني في ثلاثة أيام.', true
from public.products where slug = 'tshirt-oversize-basic';
select id, 'ياسين ح.', 4, 'جيد جداً بالنسبة للسعر. اللون مطابق للصورة.', true
from public.products where slug = 'tshirt-regular';
select id, 'سارة م.', 5, 'طلبت مقاس L وكان مناسباً تماماً. أنصح به.', true
from public.products where slug = 'tshirt-260gsm-oversized';
select id, 'كريم ز.', 5, 'تعامل محترم والتوصيل سريع. سأعيد الطلب.', true
from public.products where slug = 'tshirt-oversized-plus';
select id, 'نادية ع.', 4, 'القطعة جميلة، أخذت مقاساً أكبر قليلاً وكان أفضل.', true
from public.products where slug = 'wide-short';

commit;
